from functools import wraps
from collections import OrderedDict

def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = OrderedDict()
        frequency = {}
        hit_count = {}
        miss_count = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(kwargs.items())) if typed else args
            if key in cache:
                hit_count[key] = hit_count.get(key, 0) + 1
                frequency[key] = frequency.get(key, 0) + 1
                return cache[key]
            else:
                miss_count[key] = miss_count.get(key, 0) + 1
                result = func(*args, **kwargs)
                cache[key] = result
                frequency[key] = frequency.get(key, 0) + 1
                if len(cache) > maxsize:
                    lfu_key = min(frequency, key=frequency.get)
                    del cache[lfu_key]
                    del frequency[lfu_key]
                    del hit_count[lfu_key]
                    del miss_count[lfu_key]
                return result

        return wrapper

    return decorator
