def _legacy_mergeOrderings(orderings):
    from collections import defaultdict

    # Create a dictionary to store the positions of each element
    positions = defaultdict(list)
    for i, ordering in enumerate(orderings):
        for j, element in enumerate(ordering):
            positions[element].append((i, j))

    # Find the common suffixes
    common_suffixes = set()
    for element, pos_list in positions.items():
        if len(pos_list) > 1:
            common_suffixes.update(pos_list[1:])

    # Create a list to store the merged ordering
    merged_ordering = []
    visited = set()

    # Iterate through the orderings and add elements to the merged ordering
    for ordering in orderings:
        for element in ordering:
            if (element, positions[element][0][1]) not in visited:
                merged_ordering.append(element)
                visited.add((element, positions[element][0][1]))

    return merged_ordering
